n-version-programming.pseudocode:
def nvp_execute(versions, x):
    results = []
    for v in versions:  # 독립 개발된 N개 버전 실행
        try:
            results.append(v(x))
        except Exception:
            results.append(None)  # 실패한 버전
    counts = {}
    for r in results:
        if r is not None:
            counts[r] = counts.get(r, 0) + 1
    if not counts:
        raise RuntimeError('전 버전 실패')
    best = max(counts, key=counts.get)
    if counts[best] > len(versions) // 2:  # 과반 일치
        return best
    raise RuntimeError('합의 실패')  # 안전 상태로 전환
